<template><article class="restaurant-card" :aria-labelledby="`restaurant-${restaurant.id}-title`"><img :src="restaurant.image" :alt="`Интерьер ресторана «${restaurant.name}»`" /><div class="card-body"><div class="card-top"><p class="eyebrow">{{ restaurant.cuisine }} · {{ restaurant.district }}</p><strong class="rating" :aria-label="`Рейтинг: ${restaurant.rating} из 5`"><span aria-hidden="true">★</span> {{ restaurant.rating }}</strong></div><h2 :id="`restaurant-${restaurant.id}-title`">{{ restaurant.name }}</h2><p class="meta">{{ restaurant.address }} · {{ restaurant.metro }}</p><p>{{ restaurant.description }}</p><ul class="tags" aria-label="Особенности ресторана"><li v-for="tag in restaurant.tags" :key="tag" class="tag">{{ tag }}</li></ul><div class="card-actions"><span class="price">{{ restaurant.priceLabel }}</span><RouterLink class="btn btn-clay" :to="{ name: 'restaurant', params: { id: restaurant.id } }">Подробнее</RouterLink></div></div></article></template><script setup>defineProps({ restaurant: { type: Object, required: true } });</script>
